{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four datasets, jointly shorten histories to 64 positions and reduce depth to four causal convolution blocks, whose existing dilation schedule gives a 61-position receptive field. Increase dropout to 0.3 and lower learning rate to 7e-4 to test stronger regularization and steadier optimization with reduced computation. Preserve width, kernel size, loss, embeddings, scoring, readout, seeds and training caps. Existing checkpoint metadata and predictor construction already propagate the changed dimensions consistently.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"NEXTITNET_MAXLEN\", \"128\"))",
          "replace": "MAXLEN        = int(os.environ.get(\"NEXTITNET_MAXLEN\", \"64\"))"
        },
        {
          "find": "NUM_BLOCKS    = int(os.environ.get(\"NEXTITNET_BLOCKS\", \"8\"))",
          "replace": "NUM_BLOCKS    = int(os.environ.get(\"NEXTITNET_BLOCKS\", \"4\"))"
        },
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.2\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.3\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"1e-3\"))",
          "replace": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"7e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly set maxlen=64, num_blocks=4, dropout=0.3 and learning rate=7e-4 for all four independent category models. Existing metadata preserves predictor/checkpoint consistency."
}
